.home-flow-industry-card {
  position: absolute;
  z-index: 6;
  width: 250px;
  padding: 16px;
  border-radius: 22px;
  border: 1px solid rgba(0, 87, 184, 0.1);
  background: rgba(255, 255, 255, 0.95);
  box-shadow: 0 24px 70px rgba(6, 26, 58, 0.15);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  opacity: calc(1 - var(--shrink));
  transform-origin: center center;

  --card-hover-scale: 1;
  --card-hover-y: 0px;

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    border-color 0.3s ease,
    opacity 0.3s ease;
}

@media (hover: hover) and (pointer: fine) {
  .home-flow-tv-stage:has(.home-flow-industry-card:hover)
    .home-flow-industry-card:not(:hover) {
    --card-hover-scale: 0.92;
    filter: saturate(0.82);
  }

  .home-flow-tv-stage.has-hovered-card .home-flow-industry-card.is-pc-dimmed {
    --card-hover-scale: 0.78;
    --card-hover-y: 8px;
    filter: saturate(0.72);
  }

  .home-flow-tv-stage.has-hovered-card .home-flow-industry-card.is-pc-hovered {
    z-index: 50;
    --card-hover-scale: 1.26;
    --card-hover-y: -26px;
    filter: saturate(1);
  }

  .home-flow-industry-card:hover {
    z-index: 40;
    --card-hover-scale: 1.26;
    --card-hover-y: -26px;
    filter: saturate(1);
    border-color: rgba(9, 233, 180, 0.62);
    box-shadow:
      0 42px 118px rgba(6, 26, 58, 0.26),
      0 0 0 5px rgba(9, 233, 180, 0.12);
  }

  .home-flow-industry-card.analysis:hover {
    z-index: 60;
  }
}

.home-flow-industry-card.is-touch-active {
  z-index: 80;
  --card-hover-scale: 1.26;
  --card-hover-y: -26px;
  border-color: rgba(9, 233, 180, 0.62);
  box-shadow:
    0 42px 118px rgba(6, 26, 58, 0.26),
    0 0 0 5px rgba(9, 233, 180, 0.12);
}

.home-flow-industry-card.analysis.is-touch-active {
  z-index: 90;
}

