@media (max-width: 768px) {
  .home-flow-section {
    height: auto;
    min-height: auto;
    background:
      radial-gradient(circle at 12% 10%, rgba(0, 217, 255, 0.12), transparent 34%),
      radial-gradient(circle at 90% 18%, rgba(9, 233, 180, 0.1), transparent 30%),
      linear-gradient(180deg, #ffffff 0%, #f4f9ff 100%);
    overflow-x: hidden;
    overflow-y: visible;
  }

  .home-flow-sticky {
    position: relative;
    top: auto;
    min-height: auto;
    padding: 26px 0 52px;
    display: block;
    overflow: visible;
  }

  .home-flow-inner {
    width: min(430px, calc(100% - 32px));
    height: auto;
    min-height: 0;
    display: block;
    margin: 0 auto;
  }

  .home-flow-copy {
    max-width: none;
    transform: none;
    padding: 14px 2px 22px;
  }

  .home-flow-title {
    margin: 0;
    color: #061a3a;
    font-size: clamp(38px, 11vw, 52px);
    line-height: 1.05;
    letter-spacing: -0.04em;
    font-weight: 900;
  }

  .home-flow-desc {
    margin: 18px 0 0;
    max-width: 100%;
    color: #5e7088;
    font-size: 15px;
    line-height: 1.78;
  }

  .home-flow-capability-row {
    display: none;
  }

  .home-flow-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-top: 24px;
  }

  .home-flow-btn {
    width: 100%;
    height: 48px;
    padding: 0 14px;
    border-radius: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(6, 26, 58, 0.12);
    color: #061a3a;
    background: rgba(255, 255, 255, 0.78);
    text-decoration: none;
    font-size: 12px;
    font-weight: 750;
  }

  .home-flow-actions .home-flow-btn.is-active {
    color: #00ffb2;
    background: #173368;
    border-color: #173368;
  }

  .home-flow-btn:active {
    transform: scale(0.97);
  }

  .home-flow-tv-stage {
    display: none;
  }

  .home-flow-mobile-stage {
    display: block;
    width: 100%;
    border-radius: 0 !important;
}

  .home-flow-mobile-tv-card {
    margin-top: 24px;
    padding: 0;
    border-radius: 0 !important;
    background: transparent !important;
    border: none;
    box-shadow: none;
  }

  .home-flow-mobile-tv-screen {
    position: relative;
    min-height: 390px;
    border-radius: 0 !important;
    overflow: hidden;
    background: transparent !important;
    transition: background 0.36s ease;
  }

  .home-flow-mobile-tv-screen::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    opacity: 0.18;
    background: transparent !important;
    pointer-events: none;
    background-image: none !important;
    border-radius: 0 !important;
}

  .home-flow-mobile-tv-screen::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    background: transparent !important;
    pointer-events: none;
    background-image: none !important;
    border-radius: 0 !important;
}

  .home-flow-mobile-tv-image-layer {
    position: absolute;
    inset: 0;
    z-index: 0;
    opacity: 0.78;
    background-size: cover;
    background-position: center;
    transform: scale(1.02);
    transition:
      opacity 0.34s ease,
      transform 0.34s ease,
      background-image 0.34s ease;
    border-radius: 0 !important;
  }

  .home-flow-mobile-tv-image-layer.is-changing {
    opacity: 0.58;
    transform: scale(1.06);
    border-radius: 0 !important;
}

  .home-flow-mobile-tv-content {
    position: relative;
    z-index: 3;
    min-height: 390px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 26px 22px 22px;
    transition:
      opacity 0.24s ease,
      transform 0.24s ease;
    border-radius: 0 !important;
    background: transparent !important;
  }

  .home-flow-mobile-tv-content.is-changing {
    opacity: 0;
    transform: translateY(12px);
    border-radius: 0 !important;
}

  .home-flow-mobile-tv-topline {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
  }

  .home-flow-mobile-tv-current-index {
    color: rgba(255, 255, 255, 0.7);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
  }

  .home-flow-mobile-tv-mini-slogan {
    color: rgba(255, 255, 255, 0.86);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.02em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  .home-flow-mobile-tv-mini-slogan span {
    color: #00ffb2;
  }

  .home-flow-mobile-tv-main {
    margin-top: auto;
    border-radius: 0 !important;
}

  .home-flow-mobile-tv-title {
    margin: 0;
    color: #ffffff;
    font-size: 32px;
    line-height: 1.1;
    letter-spacing: -0.03em;
    font-weight: 900;
    text-shadow: 0 16px 44px rgba(0, 0, 0, 0.34);
  }

  .home-flow-mobile-tv-desc {
    margin: 12px 0 0;
    max-width: 300px;
    color: rgba(255, 255, 255, 0.78);
    font-size: 12px;
    line-height: 1.68;
  }

  .home-flow-mobile-tv-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 18px;
  }

  .home-flow-mobile-tv-tags span {
    display: inline-flex;
    align-items: center;
    min-height: 30px;
    padding: 6px 10px;
    border-radius: 999px;
    color: #dffef7;
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.14);
    backdrop-filter: blur(10px);
    font-size: 12px;
    font-weight: 800;
  }

