  font-size: clamp(34px, 3.2vw, 52px);
  line-height: 1.14;
  letter-spacing: -0.045em;
  font-weight: 900;
  text-shadow: none;
}

.home-advantages-desc {
  margin: 16px auto 0;
  max-width: 780px;
  color: rgba(255, 255, 255, 0.64);
  font-size: 15px;
  line-height: 1.78;
}

.home-advantage-panels {
  display: flex;
  width: 100%;
  min-height: 100vh;
}

.home-advantage-panel {
  position: relative;
  flex: 1 1 20%;
  min-width: 0;
  overflow: hidden;
  cursor: pointer;
  will-change: flex-grow, flex-basis;
  backface-visibility: hidden;
  transition:
    flex-grow 0.86s cubic-bezier(0.22, 1, 0.36, 1),
    flex-basis 0.86s cubic-bezier(0.22, 1, 0.36, 1);
}

.home-advantage-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--panel-bg);
  background-size: cover;
  background-position: center;
  transform: scale(1.02);
  transition:
    transform 0.62s ease,
    filter 0.62s ease;
}

.home-advantage-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    180deg,
    rgba(0, 0, 0, 0.12) 0%,
    rgba(0, 0, 0, 0.32) 58%,
    rgba(0, 0, 0, 0.48) 100%
  );
  transition: background 0.45s ease;
}

.home-advantage-panels:hover .home-advantage-panel {
  flex-grow: 0.82;
  flex-basis: 15%;
}

.home-advantage-panels:hover .home-advantage-panel:hover {
  flex-grow: 2.55;
  flex-basis: 40%;
}

.home-advantage-panel:hover::before {
  transform: scale(1.08);
  filter: saturate(1.08) contrast(1.03);
}

.home-advantage-panel:hover::after {
  background: linear-gradient(
    180deg,
    rgba(0, 0, 0, 0.06) 0%,
    rgba(0, 0, 0, 0.26) 52%,
    rgba(0, 0, 0, 0.6) 100%
  );
}

.home-panel-content {
  position: relative;
  z-index: 3;
  height: 100%;
  min-height: 100vh;
  padding: 0 34px 72px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  color: #ffffff;
}

.home-panel-index {
  display: block;
  margin: 0 0 18px;
  color: rgba(255, 255, 255, 0.58);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.home-panel-title {
  margin: 0;
  color: #ffffff;
  font-size: clamp(24px, 2vw, 34px);
  line-height: 1.16;
  font-weight: 900;
  letter-spacing: -0.04em;
  white-space: nowrap;
}

.home-panel-line {
  width: 52px;
  height: 2px;
  margin-top: 22px;
  background: rgba(255, 255, 255, 0.52);
  transition:
    width 0.35s ease,
    background 0.35s ease;
}

.home-panel-brief,
.home-panel-detail,
.home-panel-arrow {
  opacity: 0;
  transform: translateY(18px);
  pointer-events: none;
  transition:
    opacity 0.46s ease 0.12s,
    transform 0.46s ease 0.12s;
}

.home-panel-brief {
  margin: 24px 0 0;
  max-width: 390px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 15px;
  line-height: 1.75;
}

.home-panel-detail {
  max-width: 460px;
  max-height: 0;
  margin: 0;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.7);
  font-size: 12px;
  line-height: 1.75;
  transition:
    max-height 0.52s ease 0.16s,
    opacity 0.46s ease 0.16s,
    transform 0.46s ease 0.16s,
    margin 0.46s ease 0.16s;
}

.home-panel-arrow {
  width: 52px;
  height: 52px;
  margin-top: 28px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.22);
  font-size: 22px;
}

