.home-news-right {
  min-width: 0;
  height: 780px;
  display: flex;
  flex-direction: column;
}

.home-news-list-panel {
  display: grid;
  gap: 18px;
  flex: 1;
}

.home-news-list-item {
  position: relative;
  display: grid;
  grid-template-columns: 168px minmax(0, 1fr);
  gap: 22px;
  align-items: stretch;
  height: 165px;
  padding: 12px 0;
  overflow: hidden;
  border-bottom: 1px solid rgba(23, 51, 104, 0.13);
  transition:
    background 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.home-news-list-item::before {
  content: "";
  position: absolute;
  left: 0;
  top: 18px;
  bottom: 18px;
  width: 3px;
  background: #09e9b4;
  opacity: 0;
  transition: opacity 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.home-news-list-item:hover {
  border-color: rgba(9, 233, 180, 0.72);
  background: linear-gradient(
    90deg,
    rgba(9, 233, 180, 0.08),
    rgba(255, 255, 255, 0)
  );
}

.home-news-list-item:hover::before {
  opacity: 1;
}

.home-news-list-thumb {
  position: relative;
  height: 100%;
  min-height: 128px;
  overflow: hidden;
  background-color: #e8eff5;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
}

.home-news-list-content {
  min-width: 0;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  padding-right: 8px;
}

.home-news-list-title {
  margin: 0;
  min-width: 0;
  color: #071a35;
  font-size: 15px;
  line-height: 1.45;
  font-weight: 850;
  letter-spacing: -0.04em;
  transition: color 0.24s cubic-bezier(0.22, 1, 0.36, 1);
}

.home-news-list-item:hover .home-news-list-title {
