.home-news-list-date {
  flex-shrink: 0;
  color: rgba(23, 51, 104, 0.52);
  font-size: 12px;
  line-height: 1.45;
  font-weight: 750;
  white-space: nowrap;
}

.home-news-list-more {
  display: inline-flex;
  width: fit-content;
  color: #173368;
  text-decoration: none;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 750;
  transition: color 0.24s cubic-bezier(0.22, 1, 0.36, 1);
