.home-news-list-more:hover,
.home-news-list-item:hover .home-news-list-more {
  color: #09e9b4;
}

.home-news-bottom-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: auto;
  padding-top: 18px;
  flex-shrink: 0;
}

.home-news-view-all-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 132px;
  height: 44px;
  padding: 0 24px;
  border: 1px solid rgba(23, 51, 104, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.78);
  color: #173368;
  text-decoration: none;
  font-size: 15px;
  font-weight: 500;
  transition:
    color 0.25s cubic-bezier(0.22, 1, 0.36, 1),
