.contact-screen {
  background: #ffffff;
  border-top: 1px solid var(--line-soft);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  gap: 40px;
  align-items: stretch;
}

.demand-panel,
.inquiry-panel {
  background: var(--panel-bg);
  border: 1px solid var(--line-soft);
  overflow: hidden;
}

.demand-panel {
  padding: 46px 42px 36px;
  background: #ffffff;
}

.demand-title {
  max-width: 680px;
  color: #07182f;
  font-size: clamp(34px, 3.8vw, 54px);
  line-height: 1.12;
  font-weight: 800;
  letter-spacing: -0.055em;
}

.demand-intro {
  max-width: 760px;
  margin-top: 42px;
  color: #596a80;
  font-size: 20px;
  line-height: 2.05;
}

.demand-list {
  margin-top: 66px;
  border-top: 1px solid rgba(23, 51, 104, 0.14);
}

.demand-item {
  display: grid;
  grid-template-columns: 86px minmax(0, 1fr);
  gap: 38px;
  padding: 28px 0;
  border-bottom: 1px solid rgba(23, 51, 104, 0.14);
}

.demand-index {
  color: var(--brand-blue);
  font-size: 22px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.demand-item-title {
  color: #07182f;
  font-size: 24px;
  line-height: 1.45;
  font-weight: 800;
  margin-bottom: 10px;
}

.demand-item-text {
  color: #596a80;
  font-size: 15px;
  line-height: 1.85;
}

.inquiry-panel-head {
  padding: 30px 34px;
  border-bottom: 1px solid var(--line-soft);
  background: var(--brand-blue);
  color: #ffffff;
}

.inquiry-title {
  font-size: 28px;
  line-height: 1.35;
  font-weight: 700;
}

.inquiry-desc {
  margin-top: 10px;
  color: rgba(255, 255, 255, 0.76);
  font-size: 12px;
  line-height: 1.8;
}

.inquiry-form {
  display: grid;
  gap: 16px;
  padding: 28px 34px 34px;
  background: #ffffff;
}

.form-grid-two {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.field {
  display: grid;
  gap: 8px;
}

.field label {
  color: var(--brand-blue);
  font-size: 12px;
  line-height: 1.4;
  font-weight: 700;
}

.field input,
.field textarea,
.field select {
  width: 100%;
  border: 1px solid var(--line-mid);
  border-radius: 0;
  outline: none;
  background: #ffffff;
  color: var(--text-main);
  transition:
    border-color 0.22s var(--ease-out),
    background 0.22s var(--ease-out);
}

.field input,
.field select {
  height: 44px;
  padding: 0 12px;
  font-size: 12px;
}

.field textarea {
  min-height: 108px;
  resize: vertical;
  padding: 11px 12px;
  font-size: 12px;
  line-height: 1.72;
}

.field input:focus,
.field textarea:focus,
.field select:focus {
  border-color: var(--brand-blue);
  background: #fafcfe;
}

.other-application-field {
  display: none;
}

.other-application-field.show {
  display: grid;
}

.verify-row,
.verify-code-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 120px;
  gap: 10px;
}

.small-btn {
  min-height: 44px;
  padding: 0 14px;
  font-size: 12px;
  font-weight: 700;
}

.verify-tip {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.65;
}

.result-box {
  display: none;
  padding: 13px 14px;
  border: 1px solid var(--line-soft);
  background: var(--panel-soft);
  color: var(--text-sub);
  font-size: 12px;
  line-height: 1.8;
  white-space: pre-line;
}

.result-box.show {
  display: block;
}

.submit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 4px;
}

.submit-tip {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.65;
  flex: 1;
}

.submit-btn {
  min-width: 138px;
  min-height: 44px;
  padding: 0 22px;
  font-size: 12px;
  font-weight: 700;
}

/* =========================================================
   缂傚倸鍊搁崐鎼佸磹閹间礁纾归柟闂寸绾惧綊鏌熼梻瀵割槮缁炬儳缍婇弻鐔兼⒒鐎靛壊妲紒鐐劤缂嶅﹪寮婚悢鍏尖拻閻庨潧澹婂Σ顕€姊哄Ч鍥р偓銈夊窗濡ゅ懎桅闁告洦鍨伴崘鈧銈嗗姦濠⑩偓缂侇喖鐖煎娲箹閻愭彃顬堥梺绋匡工椤兘鐛径鎰濞达絿鎳撴禍閬嶆⒑閸撴彃浜濈紒璇插閹兘寮婚妷锔规嫼缂備礁顑嗛娆撳磿閹达附鐓曢柣妯哄暱婵秴鈹戦敍鍕毈鐎规洜鍠栭、娑橆潩椤掆偓閺併倖淇婇悙顏勨偓鏍礉閿曗偓椤潡鍩€椤掑倻纾兼い鏃囧亹閸╋綁鏌″畝瀣ɑ闁诡垱妫冩慨鈧柨婵嗘媼濡喐淇婇悙顏勨偓褎淇婇崶顒€鏋侀悹鍥ф▕閸ゆ洟鎮归崶褎鈻曢柛姘儔閺屾盯顢曢顫凹濡炪倕楠稿ú顓烆潖缂佹ɑ濯撮柛娑橈工閺嗗牓姊虹憴鍕憙妞ゆ泦鍥ㄥ仼婵犻潧顑呯粻鐟懊归敐鍛儓缂佷緤绠撳Λ鍛搭敃閵忊€愁槱缂備礁顑嗛崹鐢割敊韫囨挴鏀介柛銉ｅ劙缁ㄥ姊洪崫鍕殭婵炶绠撹棢濠㈣埖鍔栭悡鏇㈡煛閸屾稑顕滈柛銈呮处閹便劍绻濋崘鈹夸虎濠碘槅鍋勯崯顐﹀煡婢跺娼╅弶鍫氭櫆濠㈡牠姊婚崒娆戝妽闁诡喖鐖煎畷婵嗙暆閳ь剛妲愰悙瀵哥瘈闁搞儜鍛毇?Footer
   ========================================================= */
.site-footer {
  width: 100%;
  background: #f5f7fa;
  color: var(--text-main);
  border-top: 1px solid rgba(23, 51, 104, 0.08);
}

.site-footer__inner {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  padding: 56px 24px 42px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  gap: 64px;
  align-items: start;
}

.site-footer__nav-wrap {
  display: grid;
  grid-template-columns: repeat(6, minmax(100px, 1fr));
  gap: 34px;
  align-items: start;
}

.site-footer__column {
  min-width: 0;
}

.site-footer__title {
  position: relative;
  width: 100%;
  display: block;
  padding: 0 0 12px;
  margin-bottom: 20px;
  color: var(--brand-blue);
  background: transparent;
  border: 0;
  text-align: left;
  font-size: 15px;
  line-height: 1.4;
  font-weight: 800;
  cursor: default;
}

.site-footer__title::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 22px;
  height: 2px;
  background: var(--brand-cyan);
}

.site-footer__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 11px;
}

.site-footer__list a {
  color: var(--text-sub);
  font-size: 12px;
  line-height: 1.6;
  text-decoration: none;
  transition:
    color 0.25s ease,
    transform 0.25s ease;
}

.site-footer__list a:hover {
  color: var(--brand-blue);
  transform: translateX(2px);
}

.site-footer__right {
  display: grid;
  gap: 26px;
  justify-items: end;
}

.site-footer__contact {
  display: grid;
  gap: 8px;
  text-align: right;
}

.site-footer__company {
  color: var(--brand-blue);
  font-size: 24px;
  line-height: 1.45;
  font-weight: 800;
  margin: 0 0 8px;
}

.site-footer__contact-text {
  color: var(--text-sub);
  font-size: 12px;
  line-height: 1.75;
  margin: 0;
  word-break: break-word;
}

.site-footer__map-link {
  display: inline-flex;
  margin-left: 8px;
  color: var(--brand-blue);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.site-footer__map-link:hover {
  color: var(--brand-cyan);
}

.site-footer__qrcode-area {
  display: grid;
  justify-items: end;
}

.site-footer__qr-row {
  display: grid;
  grid-template-columns: repeat(2, 104px);
  gap: 14px;
}

.site-footer__qrcode-item {
  display: grid;
  justify-items: center;
  gap: 9px;
}

.site-footer__qrcode-box {
  width: 104px;
  height: 104px;
  border: 1px solid rgba(23, 51, 104, 0.14);
  background: #ffffff;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.4;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
  overflow: hidden;
}

.site-footer__qrcode-label {
  color: var(--text-sub);
  font-size: 12px;
  line-height: 1.4;
  text-align: center;
}

.site-footer__bottom {
  width: 100%;
  border-top: 1px solid rgba(23, 51, 104, 0.08);
}

.site-footer__bottom-inner {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  padding: 18px 24px 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.site-footer__bottom-left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
}

.site-footer__bottom-left p {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.6;
}

/* =========================================================
   闂傚倸鍊搁崐鎼佸磹閹间礁纾归柟闂寸绾剧懓顪冪€ｎ亝鎹ｉ柣顓炴閵嗘帒顫濋敐鍛婵°倗濮烽崑娑⑺囬悽绋挎瀬鐎广儱顦粈瀣亜閹哄棗浜鹃柟鍏兼綑閿曨亜顫忛搹鍦煓闁圭瀛╅幏杈╃磽娓氬洤鏋涢梺甯秮楠炲棗鐣濋崟顐ゎ啋缂傚倷鐒﹂敋闁逞屽墰閺佸寮诲☉鈶┾偓锕傚箣濠靛懐鏁栭梻浣侯攰濡嫰宕锕€鐓橀柟杈惧瘜閺佸﹪鏌﹀Ο渚Т闁哄鐟╁娲传閸曨厾浼囬梺鍝ュУ閹告儳危閹版澘绠抽柟鍐茬－閸犳劕顭囬鍫濈骇闁割煈鍠氭禍鏍⒒閸屾艾鈧兘鎮為敃鍌氱畺闁割偅娲栫壕褰掓煛瀹ュ海浜规繛宸簼閸嬪嫰鏌涜箛鏇炲付濞存粍顨呴—鍐Χ閸℃衼缂備胶濮甸崹鍧楀箖濞嗘劗绡€闁搞儯鍔庨崢顏呯節閻㈤潧鈧垶鍩€椤掑嫬纾婚柟鍓х帛閻撴盯鎮楅敐搴′簼妞ゃ儱鐗婇幈銊︾節閸涱噮浠╃紓渚囧枟閻熴儵鍩㈡惔銊ョ畾鐟滃秵绔熸径鎰拻濞达絽鎲＄拹锟犳煙閾忣偅灏悡銈夋煏閸繍妲归柛瀣ф櫊閺岋綁骞嬮敐鍡╂缂備胶濮惧▍鏇熺┍婵犲洤围闁告洦鍙庡Σ顕€姊洪柅鐐茶嫰婢т即鏌涜箛鏃撹€跨€殿喖顭烽幃銏ゆ惞閸︻叏绱叉繝纰樻閸ㄩ潧鈻嶉敐澶樻晞闁告洦鍘剧壕?
   ========================================================= */
@media (max-width: 1380px) {
  .screen-section {
    min-height: auto;
  }

  .news-layout,
  .contact-layout {
    grid-template-columns: 1fr;
  }

  .news-feature-card,
  .news-highlight-card,
  .news-list-panel {
    min-height: auto;
  }

  .news-list-panel {
    background: #ffffff;
    border: 1px solid var(--line-soft);
    padding: 26px;
  }

  .site-footer__inner {
    grid-template-columns: 1fr;
  }

  .site-footer__right {
    justify-items: start;
  }

  .site-footer__contact {
    text-align: left;
  }

  .site-footer__qrcode-area {
    justify-items: start;
  }
}

@media (max-width: 900px) {
  .screen-section {
    padding: 46px 16px;
  }

  .news-header {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .news-tabs {
    gap: 26px;
  }

  .news-tab-btn {
    font-size: 15px;
  }

  .news-layout {
    gap: 22px;
  }

  .news-feature-image {
    height: 240px;
  }

  .news-feature-body,
  .news-highlight-card,
  .inquiry-panel-head,
  .inquiry-form {
    padding-left: 22px;
    padding-right: 22px;
  }

  .news-list-item {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .list-thumb {
    height: 180px;
  }

  .form-grid-two,
  .verify-row,
  .verify-code-row {
    grid-template-columns: 1fr;
  }

  .submit-row {
    flex-direction: column;
    align-items: stretch;
  }

  .submit-btn {
    width: 100%;
  }

  .site-footer__inner {
    grid-template-columns: 1fr;
    gap: 34px;
    padding: 42px 18px 28px;
  }

  .site-footer__nav-wrap {
    grid-template-columns: 1fr;
    gap: 0;
    border-top: 1px solid rgba(23, 51, 104, 0.1);
  }

  .site-footer__column {
    border-bottom: 1px solid rgba(23, 51, 104, 0.1);
  }

  .site-footer__title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 0;
    padding: 16px 0;
    cursor: pointer;
  }

  .site-footer__title::after {
    content: "+";
    position: static;
    width: auto;
    height: auto;
    background: transparent;
    color: var(--brand-blue);
    font-size: 20px;
    line-height: 1;
    font-weight: 400;
  }

  .site-footer__column.is-open .site-footer__title::after {
    content: '-';
  }

  .site-footer__list {
    display: none;
    padding: 0 0 16px;
  }

  .site-footer__column.is-open .site-footer__list {
    display: grid;
  }

  .site-footer__right {
    justify-items: start;
  }

  .site-footer__contact {
    text-align: left;
  }

  .site-footer__qrcode-area {
    justify-items: start;
  }

  .site-footer__bottom-inner,
  .site-footer__bottom-left {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }
}

@media (max-width: 520px) {
  .site-footer__qr-row {
    grid-template-columns: repeat(2, 96px);
    gap: 12px;
  }

  .site-footer__qrcode-box {
    width: 96px;
    height: 96px;
  }
