.about-culture-project-section {
  padding: 86px 0 92px;
  background:
    linear-gradient(180deg, rgba(246, 247, 249, 0.96), rgba(255, 255, 255, 0.96)),
    repeating-linear-gradient(
      90deg,
      rgba(23, 51, 104, 0.04) 0 1px,
      transparent 1px 64px
    );
}

.about-culture-project-title {
  text-align: center;
  margin-bottom: 46px;
}

.about-culture-project-title i {
  margin: 14px auto 18px;
}

.about-culture-project-title p {
  margin: 0;
  color: #555555;
  font-size: 15px;
  line-height: 1.8;
}

.about-culture-project-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  align-items: stretch;
}

.about-culture-project-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: #ffffff;
  box-shadow: var(--culture-shadow-normal);
  transition:
    transform 0.36s ease,
    box-shadow 0.36s ease;
}

.about-culture-project-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--culture-shadow-hover);
}

.about-culture-project-image {
  position: relative;
  height: 235px;
  flex: 0 0 235px;
  overflow: hidden;
  background: #e6ebf3;
}

.about-culture-project-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition:
    transform 0.7s ease,
    filter 0.36s ease;
}

.about-culture-project-image::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0);
  transition: background 0.36s ease;
  pointer-events: none;
}

.about-culture-project-card:hover .about-culture-project-image img {
  transform: scale(1.06);
  filter: brightness(0.9);
}

.about-culture-project-card:hover .about-culture-project-image::after {
  background: rgba(0, 0, 0, 0.12);
}

.about-culture-project-content {
  flex: 1;
  min-height: 184px;
  padding: 28px 30px 32px;
  background: #f6f7f9;
  transition:
    background 0.36s ease,
    color 0.36s ease;
}

.about-culture-project-content h3 {
  margin: 0 0 14px;
  color: var(--culture-blue);
  font-size: 22px;
  line-height: 1.35;
  font-weight: 700;
  transition:
    color 0.36s ease,
    text-shadow 0.36s ease;
}

.about-culture-project-content p {
  margin: 0;
  color: #29415f;
  font-size: 15px;
  line-height: 1.85;
  transition: color 0.36s ease;
}

.about-culture-project-card:hover .about-culture-project-content {
  background: var(--culture-blue);
}

.about-culture-project-card:hover .about-culture-project-content h3 {
  color: var(--culture-cyan);
  text-shadow: 0 0 14px rgba(9, 233, 180, 0.26);
}

.about-culture-project-card:hover .about-culture-project-content p {
  color: rgba(9, 233, 180, 0.92);
}

