@media (max-width: 1100px) {
  .about-culture-core-list {
    grid-template-columns: repeat(3, 1fr);
  }

  .about-culture-core-item {
    border-right: 1px solid var(--culture-line);
  }

  .about-culture-core-item:last-child {
    border-right: 0;
  }

  .about-culture-brand-row,
  .about-culture-brand-row-reverse {
    grid-template-columns: 1fr;
  }

  .about-culture-brand-row-reverse .about-culture-brand-image {
    order: 1;
  }

