.about-foreach-honor-section {
  position: relative;
  padding: 96px 0 108px;
  background: #ffffff;
  overflow: hidden;
}

.about-foreach-honor-title {
  text-align: center;
  margin-bottom: 74px;
}

.about-foreach-honor-title h2 {
  color: #111827;
  font-size: clamp(34px, 3vw, 48px);
  line-height: 1.12;
  font-weight: 850;
  letter-spacing: -0.04em;
}

.about-foreach-honor-layout {
  position: relative;
  display: grid;
  grid-template-columns: 0.78fr 1.22fr;
  gap: 72px;
  align-items: center;
}

.about-foreach-honor-summary {
  min-width: 0;
  padding-bottom: 64px;
  margin-top: -200px;
}

.about-foreach-honor-summary h3 {
  color: #374151;
  font-size: clamp(28px, 2.4vw, 42px);
  line-height: 1.18;
  font-weight: 500;
  letter-spacing: 0.04em;
}

.about-foreach-honor-summary-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  margin-top: 48px;
  max-width: 520px;
}

