.about-foreach-honor-summary-stat:last-child {
  border-right: none;
}

.about-foreach-honor-summary-number {
  color: #111827;
  font-size: 68px;
  font-weight: 850;
  line-height: 1;
  letter-spacing: -0.06em;
}

.about-foreach-honor-summary-plus {
  display: inline-block;
  margin-left: 4px;
  font-size: 0.38em;
  font-weight: 800;
  transform: translateY(-0.06em);
}

.about-foreach-honor-summary-label {
  margin-top: 10px;
  color: #69727e;
  font-size: 15px;
  font-weight: 700;
}

.about-foreach-honor-display {
  position: relative;
  min-height: 420px;
}

.about-foreach-honor-main-cert {
  position: relative;
  z-index: 2;
  width: min(610px, 100%);
  height: 320px;
  margin: 0 auto;
  border: 8px solid #4a4f57;
  background: #ffffff;
  box-shadow: 0 28px 70px rgba(7, 26, 58, 0.16);
}

.about-foreach-honor-main-cert::before {
  content: "";
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(17, 24, 39, 0.16);
  background:
    linear-gradient(135deg, rgba(223, 227, 232, 0.88), rgba(247, 248, 250, 0.96)),
    repeating-linear-gradient(
      135deg,
      rgba(23, 51, 104, 0.06) 0 1px,
      transparent 1px 14px
    );
}

.about-foreach-honor-thumb-row {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 28px;
  margin-top: 58px;
  margin-left: -420px;
  width: calc(100% + 420px);
}

.about-foreach-honor-thumb {
  height: 120px;
  border: 5px solid #4a4f57;
  background: linear-gradient(135deg, #dfe3e8 0%, #c2c8d1 50%, #eef1f5 100%);
  box-shadow: 0 14px 36px rgba(7, 26, 58, 0.08);
}

.about-foreach-honor-thumb::before {
  background: linear-gradient(90deg, rgba(7, 26, 58, 0.1), rgba(255, 255, 255, 0.12));
}

.about-foreach-honor-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-top: 46px;
}

.about-foreach-honor-arrow {
  width: 50px;
  height: 38px;
  border: none;
  display: grid;
  place-items: center;
  color: #ffffff;
  background: var(--about-foreach-brand-blue);
  font-size: 20px;
  cursor: default;
}

.about-foreach-honor-arrow-next {
  color: #7d8793;
  background: #ffffff;
}

