@media (max-width: 1180px) {
  .about-foreach-intro-layout {
    grid-template-columns: 1fr;
  }

  .about-foreach-advantage-stats {
    grid-template-columns: repeat(2, 1fr);
    row-gap: 36px;
  }

  .about-foreach-honor-layout {
    grid-template-columns: 1fr;
  }

  .about-foreach-honor-summary {
    margin-top: 0;
    padding-bottom: 0;
  }

  .about-foreach-honor-thumb-row {
    margin-left: 0;
    width: 100%;
  }
}

@media (max-width: 860px) {
  .about-foreach-hero {
    height: 520px;
    min-height: 420px;
  }

  .about-foreach-hero h1 {
    font-size: 42px;
  }

  .about-foreach-hero p,
  .about-foreach-intro-copy p {
    font-size: 15px;
  }

  .about-foreach-intro-section,
  .about-foreach-honor-section {
    padding: 82px 0;
  }

  .about-foreach-advantage-number {
    font-size: 54px;
  }

  .about-foreach-advantage-image {
    min-height: 300px;
  }

  .about-foreach-honor-summary-number {
    font-size: 58px;
  }
}

@media (max-width: 640px) {
  .about-foreach-container,
  .about-foreach-hero-content,
  .about-foreach-advantage-panel {
    width: calc(100% - 32px);
  }

  .about-foreach-intro-layout {
    gap: 48px;
  }

  .about-foreach-intro-copy p {
    margin-top: 32px;
  }

  .about-foreach-advantage-stats,
  .about-foreach-honor-summary-stats,
  .about-foreach-honor-thumb-row {
    grid-template-columns: 1fr;
  }

  .about-foreach-advantage-stat {
    padding: 0;
  }

  .about-foreach-video-card {
    min-height: 300px;
  }

  .about-foreach-advantage-number {
    font-size: 48px;
  }

  .about-foreach-honor-summary-stat {
    padding-right: 0;
    border-right: none;
    text-align: center;
  }

  .about-foreach-honor-summary h3 {
    text-align: center;
  }
