/* ABOUT_FOREACH_HONOR_REFERENCE_LAYOUT_START */
.about-foreach-honor-section {
  padding: 10px 0 72px;
  background: #ffffff;
  scroll-margin-top: 82px;
}

.about-foreach-page .about-foreach-honor-section > .about-foreach-container {
  width: min(1520px, calc(100% - 64px));
  max-width: 1520px;
  margin-right: auto;
  margin-left: auto;
}

.about-foreach-honor-title {
  margin-bottom: 48px;
  text-align: center;
}

.about-foreach-honor-title h2 {
  color: #173368;
  font-size: clamp(38px, 3vw, 46px);
  line-height: 1.12;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.about-foreach-honor-layout {
  display: grid;
  grid-template-columns: 450px minmax(0, 1fr);
  column-gap: 32px;
  align-items: start;
  width: 100%;
}

.about-foreach-honor-summary {
  min-width: 0;
  margin-top: 0;
  padding: 4px 0 0 16px;
}

.about-foreach-honor-summary h3 {
  color: #173368;
  font-size: 40px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.025em;
}

.about-foreach-honor-summary-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  width: 100%;
  max-width: none;
  margin-top: 40px;
}

.about-foreach-honor-summary-stat {
  min-width: 0;
  padding-right: 0;
  border-right: none;
}

.about-foreach-honor-summary-number {
  color: #173368;
  font-size: 74px;
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.045em;
}

.about-foreach-honor-summary-plus {
  color: #173368;
  margin-left: 4px;
  font-size: 26px;
  font-weight: 700;
  vertical-align: 13px;
  transform: none;
}

.about-foreach-honor-summary-label {
  margin-top: 12px;
  color: #173368;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.45;
  white-space: nowrap;
}

.about-foreach-honor-board {
  display: grid;
  gap: 30px;
  min-width: 0;
  width: 100%;
}

.about-foreach-honor-top-row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
  align-items: stretch;
  height: 360px;
}

.about-foreach-honor-main-cert {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 360px;
  margin: 0;
  border: 6px solid #454b55;
  background: #ffffff;
  box-shadow: none;
  overflow: hidden;
}

.about-foreach-honor-main-cert::before {
  display: none;
}

.about-foreach-honor-main-cert-image,
.about-foreach-honor-iso-cert,
.about-foreach-honor-middle-image,
.about-foreach-honor-a4-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.about-foreach-honor-iso-cert {
  min-width: 0;
  height: 360px;
  background: transparent;
  box-shadow: none;
}

.about-foreach-honor-middle-row {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) minmax(0, 1.08fr);
  gap: 25px;
  align-items: center;
  width: calc(100% + 310px);
  margin-left: -310px;
  margin-top: 0;
}

.about-foreach-honor-middle-image {
  height: 280px;
  background: transparent;
  box-shadow: none;
}

.about-foreach-honor-a4-row {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 16px;
  width: 100%;
  margin-top: 40px;
  align-items: start;
}

.about-foreach-honor-a4-card {
  min-width: 0;
  text-align: center;
}

.about-foreach-honor-a4-image-wrap {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  width: 100%;
  height: 240px;
  overflow: hidden;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.about-foreach-honor-a4-image-wrap::before {
  display: none;
}

