.about-history-inner-banner {
  position: relative;
  height: 520px;
  min-height: 420px;
  overflow: hidden;
  background:
    linear-gradient(
      90deg,
      rgba(7, 27, 58, 0.92) 0%,
      rgba(23, 51, 104, 0.78) 52%,
      rgba(7, 27, 58, 0.42) 100%
    ),
    var(--history-banner-image) center center / cover no-repeat,
    linear-gradient(135deg, #071b3a 0%, #173368 100%);
}

.about-history-inner-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.045) 1px, transparent 1px);
  background-size: 58px 58px;
  opacity: 0.55;
  pointer-events: none;
}

.about-history-inner-banner-content {
  position: relative;
  z-index: 2;
  width: min(1500px, calc(100% - 80px));
  min-height: 420px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  color: #ffffff;
}

.about-history-inner-banner-eyebrow {
  margin-bottom: 14px;
  color: #09e9b4;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.about-history-inner-banner h1 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(38px, 4vw, 58px);
  line-height: 1.1;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.about-history-inner-banner p {
  max-width: none;
  margin: 16px auto 0;
  color: rgba(255, 255, 255, 1);
  font-size: 37px;
  line-height: 1.8;
  text-align: center;
