.quality-path-loop {
  position: relative;
  margin-top: 34px;
  padding: 34px 42px;
  display: grid;
  grid-template-columns: minmax(0, 0.58fr) minmax(0, 1.42fr);
  gap: 56px;
  align-items: center;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid rgba(23, 51, 104, 0.10);
  border-left: 3px solid #09e9b4;
  backdrop-filter: blur(14px);
  overflow: hidden;
  transition:
    transform 0.28s ease,
    box-shadow 0.28s ease,
    border-color 0.28s ease,
    background 0.28s ease;
}

.quality-path-loop::before {
  content: "";
  position: absolute;
  left: -40%;
  top: 0;
  width: 38%;
  height: 100%;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(9, 233, 180, 0.12) 48%,
    transparent 100%
  );
  opacity: 0;
  transform: skewX(-16deg);
}

.quality-path-loop:hover {
  transform: translateY(-4px);
  background: rgba(255, 255, 255, 0.92);
  border-color: rgba(9, 233, 180, 0.38);
  box-shadow: 0 16px 34px rgba(6, 26, 58, 0.08);
}

.quality-path-loop:hover::before {
  opacity: 1;
  animation: qualityLoopSweep 1.15s ease forwards;
}

@keyframes qualityLoopSweep {
  from {
    left: -42%;
  }

  to {
    left: 104%;
  }
}

.quality-path-loop-title {
  position: relative;
  z-index: 2;
  color: #173368;
  font-size: 28px;
  line-height: 1.32;
  font-weight: 650;
  letter-spacing: -0.04em;
  transition: color 0.28s ease;
}

.quality-path-loop:hover .quality-path-loop-title {
  color: #09e9b4;
}

.quality-path-loop-text {
  position: relative;
  z-index: 2;
  color: #627288;
  font-size: 15px;
  line-height: 1.9;
  transition: color 0.28s ease;
}

.quality-path-loop:hover .quality-path-loop-text {
  color: #4f6078;
}

