  --supply-gap: 34px;
}

.rm-supply-window {
  overflow: hidden;
  padding: 20px 0;
}

.rm-supply-track {
  display: flex;
  gap: var(--supply-gap);
  align-items: center;
  padding: 0 calc((100% - var(--supply-card-width)) / 2);
  transition: transform 0.48s ease;
  will-change: transform;
}

.rm-supply-card {
  position: relative;
  flex: 0 0 var(--supply-card-width);
  min-height: 420px;
  overflow: hidden;
  border: 0;
  padding: 0;
  text-align: left;
  opacity: 0.46;
  cursor: pointer;
  transform: scale(0.82);
  transform-origin: center center;
  background: #eef4f9;
  transition:
    transform 0.38s ease,
    opacity 0.38s ease,
    box-shadow 0.38s ease;
}

.rm-supply-card.is-active {
  opacity: 1;
  transform: scale(1.16);
  z-index: 3;
  box-shadow: 0 30px 82px rgba(23, 51, 104, 0.16);
}

.rm-supply-card.is-neighbor {
  opacity: 0.78;
  transform: scale(0.92);
  z-index: 2;
}

.rm-supply-image {
  object-fit: cover;
  transition: transform 0.36s ease;
}

.rm-supply-card:hover .rm-supply-image {
  transform: scale(1.04);
}

.rm-supply-mask {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    180deg,
    rgba(8, 22, 48, 0.04) 0%,
    rgba(8, 22, 48, 0.18) 42%,
    rgba(8, 22, 48, 0.78) 100%
  );
  pointer-events: none;
}

.rm-supply-copy {
  position: absolute;
  left: 36px;
  right: 36px;
  bottom: 34px;
  z-index: 2;
  color: #ffffff;
}

.rm-supply-title {
  margin-bottom: 14px;
  color: #ffffff;
  font-size: 32px;
  font-weight: 600;
  line-height: 1.32;
  transition: color 0.24s ease;
}

.rm-supply-card:hover .rm-supply-title,
.rm-supply-card.is-active .rm-supply-title {
  color: var(--rm-cyan);
}

.rm-supply-desc {
  max-width: 520px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 15px;
  line-height: 1.85;
}

.rm-supply-navigator {
  display: grid;
  grid-template-columns: 1fr;
  align-items: center;
  margin-top: 34px;
}

.rm-supply-timeline {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  align-items: start;
  gap: 0;
  min-height: 74px;
}

.rm-supply-timeline::before {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: 63px;
  height: 1px;
  background: rgba(23, 51, 104, 0.22);
}

.rm-supply-nav-item {
  position: relative;
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: 20px;
  border: 0;
  background: transparent;
  color: var(--rm-blue);
  font-family: inherit;
  font-size: 20px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0.62;
  transition:
    color 0.22s ease,
    opacity 0.22s ease,
    transform 0.22s ease;
}

.rm-supply-nav-item:hover {
  color: var(--rm-blue);
  opacity: 1;
  transform: translateY(-2px);
}

.rm-supply-nav-item.is-active {
  color: var(--rm-cyan);
  opacity: 1;
  transform: translateY(-2px);
}

.rm-supply-nav-dot {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(23, 51, 104, 0.34);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  transition:
    border-color 0.22s ease,
    transform 0.22s ease,
    background 0.22s ease;
}

.rm-supply-nav-dot::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--rm-blue);
  transition:
    background 0.22s ease,
    transform 0.22s ease;
}

.rm-supply-nav-item.is-active .rm-supply-nav-dot {
  border-color: rgba(9, 233, 180, 0.72);
  background: rgba(9, 233, 180, 0.1);
  transform: scale(1.16);
}

.rm-supply-nav-item.is-active .rm-supply-nav-dot::before {
  background: var(--rm-cyan);
  transform: scale(1.18);
}
