.rm-cta {
  position: relative;
  padding: 104px 0;
  overflow: hidden;
  background: var(--rm-blue-dark);
}

.rm-cta-bg {
  object-fit: cover;
}

.rm-cta-mask {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    90deg,
    rgba(8, 22, 48, 0.92) 0%,
    rgba(8, 22, 48, 0.72) 100%
  );
}

.rm-cta > .rm-container {
  position: relative;
  z-index: 2;
}

.rm-cta-panel {
  min-height: 360px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 60px;
  align-items: center;
  padding: 70px;
  color: #ffffff;
}

.rm-cta-title {
  color: #ffffff;
  font-size: 34px;
  font-weight: 600;
  line-height: 1.4;
}

.rm-cta-desc {
  max-width: 760px;
  margin-top: 20px;
  color: rgba(255, 255, 255, 0.76);
  font-size: 15px;
  line-height: 1.9;
}

